Read the item quantities in E7:K15 and the unit-price table from the right-hand labels. Compute each final price point as the sum of quantity × matching unit price for the seven item columns. Write the nine numeric results into T7:T15 of the copied workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Sheet1"
if sheet_name not in wb.sheetnames:
    sheet_name = wb.active.title

ws = wb[sheet_name]
vws = vals[sheet_name]

def is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def to_float(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return 0.0
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip()
    if not s:
        return 0.0
    try:
        return float(s)
    except ValueError:
        return 0.0

# Extract unit prices for Item 1..Item 7.
prices = [None] * 7
for i in range(7):
    r = 13 + i
    y = vws.cell(row=r, column=25).value  # Y
    x = vws.cell(row=r, column=24).value  # X
    if is_number(y):
        prices[i] = float(y)
    elif is_number(x):
        prices[i] = float(x)

# Fallback: match item labels and take the adjacent numeric value.
if any(p is None for p in prices):
    labels = []
    for c in range(5, 12):
        v = vws.cell(row=6, column=c).value
        labels.append(str(v).strip() if v is not None else f"Item {c - 4}")

    for i, lab in enumerate(labels):
        if prices[i] is not None:
            continue

        found = False
        target = lab.lower()
        for r in range(7, vws.max_row + 1):
            for c in range(1, vws.max_column + 1):
                cell = vws.cell(row=r, column=c).value
                if cell is not None and str(cell).strip().lower() == target:
                    for dc in (1, -1):
                        v = vws.cell(row=r, column=c + dc).value
                        if is_number(v):
                            prices[i] = float(v)
                            found = True
                            break
                    if found:
                        break
            if found:
                break

        if not found:
            prices[i] = 0.0

prices = [float(p) if p is not None else 0.0 for p in prices]
print("prices:", prices)

# Compute final price point for T7:T15.
for r in range(7, 16):
    total = 0.0
    for i, c in enumerate(range(5, 12)):  # E..K
        q = to_float(vws.cell(row=r, column=c).value)
        total += q * prices[i]

    if abs(total - round(total)) < 1e-9:
        total = int(round(total))
    else:
        total = round(total, 2)

    ws.cell(row=r, column=20).value = total  # T
    print(r, total)

wb.save(OUT)
```

